import React, { useEffect, useRef, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { AlertTriangle, ChevronLeft, ChevronRight, Loader2, Send, Trash2, Upload } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { apiFetch, getApiBase } from "./api";
import { h, f } from "./h";
import { Badge, Button, Field, GlassCard, GlassPanel, InlineNotice, SelectInput, TextArea } from "./ui";
import { BuyerLayout, CartDrawer } from "./screensBuyer";

/** Buyer-facing issue types (matches backend category enum). */
const BUYER_PROBLEMS = [
  { value: "item_not_delivered", label: "Item not delivered" },
  { value: "wrong_item_received", label: "Wrong item received" },
  { value: "fake_misleading_product", label: "Fake / misleading product" },
  { value: "seller_not_responding", label: "Seller not responding" },
  { value: "other", label: "Other" }
];

/** Vendor-facing issue types. */
const VENDOR_PROBLEMS = [
  { value: "buyer_no_show", label: "Buyer didn't show up" },
  { value: "payment_not_confirmed", label: "Payment not confirmed" },
  { value: "fraudulent_activity", label: "Fraudulent activity" },
  { value: "abuse_misconduct", label: "Abuse / misconduct" },
  { value: "other", label: "Other" }
];

/** Labels for table + admin alignment (includes legacy keys). */
const CATEGORY_LABELS = {
  item_not_delivered: "Item not delivered",
  wrong_item_received: "Wrong item received",
  fake_misleading_product: "Fake / misleading product",
  seller_not_responding: "Seller not responding",
  buyer_no_show: "Buyer didn't show up",
  payment_not_confirmed: "Payment not confirmed",
  fraudulent_activity: "Fraudulent activity",
  abuse_misconduct: "Abuse / misconduct",
  fake_seller: "Fake / misleading seller",
  scam: "Scam",
  bad_product: "Bad product / listing",
  chat_abuse: "Abuse in messages",
  other: "Other"
};

function reportStatusTone(s) {
  if (s === "open") return "warn";
  if (s === "in_review") return "info";
  if (s === "resolved") return "success";
  if (s === "dismissed") return "neutral";
  return "neutral";
}

function fmtDate(d) {
  if (!d) return "—";
  try {
    return new Date(d).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
  } catch {
    return "—";
  }
}

function shortId(id) {
  if (!id) return "—";
  return `#${String(id).slice(-8).toUpperCase()}`;
}

function categoryLabel(v) {
  return CATEGORY_LABELS[v] || v;
}

function ReportsPager({ page, total, limit, onPage }) {
  const pages = Math.max(1, Math.ceil((total || 0) / (limit || 1)));
  const start = total === 0 ? 0 : (page - 1) * limit + 1;
  const end = Math.min(page * limit, total);
  return h("div", { className: "flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500 dark:text-slate-400" }, [
    h("span", { key: "t" }, `Showing ${start}-${end} of ${total} · page ${page}/${pages}`),
    h("div", { key: "b", className: "flex items-center gap-1" }, [
      h(
        "button",
        {
          key: "p",
          type: "button",
          disabled: page <= 1,
          onClick: () => onPage(Math.max(1, page - 1)),
          className:
            "flex items-center gap-1 rounded-xl border border-violet-200/80 bg-white/60 px-2.5 py-1.5 text-xs font-medium text-violet-800 hover:bg-violet-50 disabled:opacity-40 dark:border-violet-500/20 dark:bg-white/5 dark:text-violet-200 dark:hover:bg-violet-950/40"
        },
        [h(ChevronLeft, { key: "i", className: "h-3.5 w-3.5" }), "Prev"]
      ),
      h(
        "button",
        {
          key: "n",
          type: "button",
          disabled: page >= pages,
          onClick: () => onPage(Math.min(pages, page + 1)),
          className:
            "flex items-center gap-1 rounded-xl border border-violet-200/80 bg-white/60 px-2.5 py-1.5 text-xs font-medium text-violet-800 hover:bg-violet-50 disabled:opacity-40 dark:border-violet-500/20 dark:bg-white/5 dark:text-violet-200 dark:hover:bg-violet-950/40"
        },
        ["Next", h(ChevronRight, { key: "i", className: "h-3.5 w-3.5" })]
      )
    ])
  ]);
}

/**
 * @param {{ variant: "buyer" | "vendor" }} props
 */
function ReportPanelInner({ variant }) {
  const { accessToken } = useAuth();
  const { toast } = useNotice();
  const [searchParams] = useSearchParams();
  const fileRef = useRef(null);

  const problemOptions = variant === "vendor" ? VENDOR_PROBLEMS : BUYER_PROBLEMS;
  const defaultCat = problemOptions[0].value;

  const [category, setCategory] = useState(defaultCat);
  const [description, setDescription] = useState("");
  const [targetType, setTargetType] = useState("other");
  const [targetId, setTargetId] = useState("");
  const [evidenceUrls, setEvidenceUrls] = useState([]);
  const [evidenceUploading, setEvidenceUploading] = useState(false);
  const [submitErr, setSubmitErr] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const [contextOrder, setContextOrder] = useState(null);
  const [contextProduct, setContextProduct] = useState(null);
  const [contextErr, setContextErr] = useState("");

  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [listNonce, setListNonce] = useState(0);
  const [listErr, setListErr] = useState("");
  const limit = 15;

  const backHref = variant === "vendor" ? "/vendor/dashboard" : "/";
  const backLabel = variant === "vendor" ? "Vendor dashboard" : "Home";

  useEffect(() => {
    const p = searchParams.get("product");
    const o = searchParams.get("order");
    const u = searchParams.get("user");
    if (p) {
      setTargetType("product");
      setTargetId(p);
    } else if (o) {
      setTargetType("order");
      setTargetId(o);
    } else if (u) {
      setTargetType("user");
      setTargetId(u);
    }
  }, [searchParams]);

  useEffect(() => {
    if (!accessToken || targetType !== "order" || !targetId) {
      setContextOrder(null);
      return;
    }
    let cancelled = false;
    setContextErr("");
    (async () => {
      try {
        const d = await apiFetch(`/api/orders/${targetId}`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (!cancelled && d.order) setContextOrder(d.order);
      } catch (ex) {
        if (!cancelled) {
          setContextOrder(null);
          setContextErr(ex.message || "Could not load order details for this report.");
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [accessToken, targetType, targetId]);

  useEffect(() => {
    if (!targetId || targetType !== "product") {
      setContextProduct(null);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const d = await apiFetch(`/api/products/${targetId}`);
        if (!cancelled && d.product) setContextProduct(d.product);
      } catch {
        if (!cancelled) setContextProduct(null);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [targetId, targetType]);

  useEffect(() => {
    if (!accessToken) return;
    let cancelled = false;
    setListErr("");
    (async () => {
      try {
        const qs = new URLSearchParams({ page: String(page), limit: String(limit) });
        const d = await apiFetch(`/api/reports/me?${qs.toString()}`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (!cancelled) {
          setRows(d.reports || []);
          setTotal(d.total || 0);
        }
      } catch (ex) {
        if (!cancelled) setListErr(ex.message || "Could not load your reports.");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [accessToken, page, listNonce]);

  const addEvidenceFile = async (file) => {
    if (!file || !accessToken) return;
    if (evidenceUrls.length >= 3) {
      setSubmitErr("You can attach at most 3 images.");
      return;
    }
    const ok = /^image\/(jpeg|png|webp)$/i.test(file.type) || /\.(jpe?g|png|webp)$/i.test(file.name);
    if (!ok) {
      setSubmitErr("Use PNG, JPG, or WebP (max 5 MB each).");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setSubmitErr("Each file must be 5 MB or smaller.");
      return;
    }
    setSubmitErr("");
    setEvidenceUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch(`${getApiBase()}/api/uploads/report-evidence`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        body: fd,
        credentials: "include"
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        const msg = data?.error?.message || data?.message || `Upload failed (${res.status})`;
        throw new Error(msg);
      }
      if (data.url) setEvidenceUrls((prev) => [...prev, data.url].slice(0, 3));
    } catch (ex) {
      setSubmitErr(ex.message || "Upload failed.");
    } finally {
      setEvidenceUploading(false);
    }
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setSubmitErr("");
    if (!accessToken) return;
    if (String(description).trim().length < 10) {
      setSubmitErr("Please describe the issue in at least 10 characters.");
      return;
    }
    setSubmitting(true);
    try {
      await apiFetch("/api/reports", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: {
          category,
          description: description.trim(),
          targetType,
          targetId: String(targetId).trim() || undefined,
          evidenceUrls: evidenceUrls.length ? evidenceUrls : undefined
        }
      });
      toast("Report submitted. Our team will review it.", { variant: "success" });
      setDescription("");
      setCategory(defaultCat);
      setEvidenceUrls([]);
      setPage(1);
      setListNonce((n) => n + 1);
    } catch (ex) {
      setSubmitErr(ex.message || "Could not submit report.");
    } finally {
      setSubmitting(false);
    }
  };

  const catOptions = problemOptions.map((c) => h("option", { key: c.value, value: c.value }, c.label));

  const orderLine =
    contextOrder && contextOrder.items && contextOrder.items.length
      ? contextOrder.items.map((it) => `${it.name} (×${it.quantity ?? 1})`).join(", ")
      : null;
  const vendorOrBuyerLabel = (() => {
    if (!contextOrder) return null;
    if (variant === "buyer") {
      const s = contextOrder.items && contextOrder.items[0];
      if (s && s.sellerName) return String(s.sellerName);
      if (s && s.sellerLabel) return String(s.sellerLabel);
    }
    if (variant === "vendor" && contextOrder.buyerLabel) return String(contextOrder.buyerLabel);
    if (variant === "vendor" && contextOrder.buyerName) return String(contextOrder.buyerName);
    return "—";
  })();

  const showContext = Boolean(
    (targetType === "order" && (targetId || contextOrder)) ||
      (targetType === "product" && (contextProduct || targetId)) ||
      (targetType === "user" && targetId)
  );

  return h("div", { className: "w-full max-w-3xl px-0 py-6 sm:py-8" }, [
    h("div", { key: "nav", className: "mb-6" }, [
      h(
        Link,
        {
          to: backHref,
          className: "text-sm font-medium text-violet-600 hover:underline dark:text-violet-300"
        },
        `← ${backLabel}`
      ),
      h("div", { key: "hd", className: "mt-5" }, [
        h("div", { className: "flex items-start gap-4" }, [
          h(
            "div",
            {
              className:
                "flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-violet-100 text-violet-700 shadow-sm dark:bg-violet-500/20 dark:text-violet-200"
            },
            h(AlertTriangle, { className: "h-6 w-6" })
          ),
          h("div", { className: "min-w-0 flex-1" }, [
            h(
              "h1",
              { className: "font-display text-2xl font-bold tracking-tight text-slate-900 dark:text-white" },
              variant === "vendor" ? "Report an issue" : "Report an issue"
            ),
            h(
              "p",
              { className: "mt-1 text-sm leading-relaxed text-slate-600 dark:text-slate-400" },
              variant === "vendor"
                ? "Flag a problem with a buyer or an order. Admins will review your report and may follow up by email."
                : "Let us know if something went wrong with an order, product, or seller. We review every report."
            )
          ])
        ])
      ])
    ]),

    h(
      GlassPanel,
      {
        key: "form",
        className: "mb-8 !border-violet-200/60 !bg-white/90 shadow-lg shadow-slate-200/40 dark:!border-violet-500/15 dark:!bg-night-900/50 dark:shadow-none"
      },
      [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "What seems to be the problem?"),
        h(
          "p",
          { className: "mt-1 text-sm text-slate-500 dark:text-slate-400" },
          "Be honest and specific. False or abusive reports can affect your account."
        ),
        h(
          "form",
          { className: "mt-5 space-y-5", onSubmit },
          [
            h(
              Field,
              { label: "Issue type" },
              h(
                SelectInput,
                {
                  value: category,
                  onChange: (e) => setCategory(e.target.value),
                  required: true,
                  className: "!border-violet-200/80 dark:!border-violet-500/20"
                },
                catOptions
              )
            ),
            showContext
              ? h(
                  "div",
                  {
                    key: "ctx",
                    className:
                      "rounded-2xl border border-violet-200/80 bg-violet-50/80 p-4 text-sm dark:border-violet-500/20 dark:bg-violet-950/30"
                  },
                  [
                    h("p", { key: "l", className: "text-[10px] font-bold uppercase tracking-wider text-violet-600 dark:text-violet-300" }, "Context"),
                    targetType === "order" && h("p", { key: "o", className: "mt-1 text-slate-800 dark:text-slate-200" }, [
                      h("span", { className: "font-medium text-slate-500" }, "Order: "),
                      shortId((contextOrder && contextOrder.id) || targetId)
                    ]),
                    targetType === "order" && orderLine
                      ? h("p", { key: "i", className: "mt-1 text-slate-700 dark:text-slate-300" }, [h("span", { className: "font-medium text-slate-500" }, "Items: "), orderLine])
                      : null,
                    targetType === "order" && vendorOrBuyerLabel && vendorOrBuyerLabel !== "—"
                      ? h("p", { key: "p", className: "mt-1 text-slate-700 dark:text-slate-300" }, [
                          h("span", { className: "font-medium text-slate-500" }, variant === "buyer" ? "Vendor: " : "Customer: "),
                          vendorOrBuyerLabel
                        ])
                      : null,
                    targetType === "product" &&
                      h("p", { key: "pr", className: "mt-1 text-slate-800 dark:text-slate-200" }, [
                        h("span", { className: "font-medium text-slate-500" }, "Product: "),
                        (contextProduct && (contextProduct.name || contextProduct.title)) || shortId(targetId)
                      ]),
                    targetType === "user" &&
                      h("p", { key: "u", className: "mt-1 font-mono text-xs text-slate-700 dark:text-slate-300" }, [h("span", { className: "font-sans font-medium text-slate-500" }, "User ID: "), targetId])
                  ].filter(Boolean)
                )
              : null,
            contextErr ? h("p", { key: "oerr", className: "text-xs text-amber-700 dark:text-amber-200" }, contextErr) : null,
            h(Field, { key: "desc", label: "Please describe the issue" }, h(TextArea, {
              value: description,
              onChange: (e) => setDescription(e.target.value.slice(0, 4000)),
              rows: 5,
              required: true,
              placeholder: "What happened, when, and any other details that help us investigate.",
              className: "min-h-[128px] !border-slate-200/90 dark:!border-white/10"
            })),
            h("p", { key: "cnt", className: "text-right text-xs text-slate-500" }, `${description.length}/4000`),

            h("div", { key: "up", className: "space-y-2" }, [
              h("span", { className: "text-xs font-semibold uppercase tracking-wide text-slate-600 dark:text-slate-400" }, "Upload evidence (optional)"),
              h("p", { className: "text-xs text-slate-500 dark:text-slate-500" }, "PNG or JPG, up to 5 MB each (max 3 images)."),
              h(
                "button",
                {
                  type: "button",
                  disabled: evidenceUploading || evidenceUrls.length >= 3,
                  onClick: () => fileRef.current?.click(),
                  onDragOver: (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  },
                  onDrop: (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    const f = e.dataTransfer.files && e.dataTransfer.files[0];
                    if (f) addEvidenceFile(f);
                  },
                  className:
                    "flex w-full flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed border-violet-200/90 bg-violet-50/50 px-4 py-8 text-center transition hover:border-violet-400 hover:bg-violet-50/80 disabled:opacity-50 dark:border-violet-500/25 dark:bg-violet-950/20 dark:hover:border-violet-400/50"
                },
                [
                  evidenceUploading
                    ? h(Loader2, { key: "ld", className: "h-8 w-8 animate-spin text-violet-600 dark:text-violet-300" })
                    : h(Upload, { key: "ic", className: "h-8 w-8 text-violet-600 dark:text-violet-300" }),
                  h("p", { key: "t1", className: "text-sm font-medium text-slate-800 dark:text-slate-100" }, "Click to upload or drag and drop"),
                  h("p", { key: "t2", className: "text-xs text-slate-500" }, "Helps us resolve issues faster.")
                ]
              ),
              h("input", {
                ref: fileRef,
                type: "file",
                accept: "image/png,image/jpeg,image/webp",
                className: "hidden",
                onChange: (e) => {
                  const f = e.target.files && e.target.files[0];
                  e.target.value = "";
                  if (f) addEvidenceFile(f);
                }
              }),
              evidenceUrls.length
                ? h("div", { key: "thumbs", className: "flex flex-wrap gap-2" }, evidenceUrls.map((url, i) =>
                    h("div", { key: url, className: "group relative" }, [
                      h("img", { src: url, alt: "", className: "h-20 w-20 rounded-xl border border-white/20 object-cover" }),
                      h(
                        "button",
                        {
                          type: "button",
                          "aria-label": "Remove",
                          className:
                            "absolute -right-1.5 -top-1.5 flex h-7 w-7 items-center justify-center rounded-full bg-rose-600 text-white shadow-md opacity-0 transition group-hover:opacity-100",
                          onClick: () => setEvidenceUrls((u) => u.filter((_, j) => j !== i))
                        },
                        h(Trash2, { className: "h-3.5 w-3.5" })
                      )
                    ])
                  ))
                : null
            ]),

            submitErr ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setSubmitErr("") }, submitErr) : null,
            h(
              Button,
              {
                key: "sub",
                type: "submit",
                loading: submitting,
                className:
                  "w-full !bg-violet-600 !text-white shadow-md !shadow-violet-900/20 hover:!bg-violet-700 dark:!bg-violet-600 dark:hover:!bg-violet-500"
              },
              [h(Send, { key: "i", className: "h-4 w-4" }), "Submit report"]
            )
          ].filter(Boolean)
        )
      ]
    ),

    h("h2", { key: "list-h", className: "mb-3 text-lg font-semibold text-slate-900 dark:text-white" }, "Your reports"),
    listErr ? h(InlineNotice, { key: "le", variant: "error", onDismiss: () => setListErr("") }, listErr) : null,
    h(
      GlassCard,
      {
        key: "tbl",
        className: "!overflow-x-auto !border-violet-200/50 !p-0 dark:!border-violet-500/10"
      },
      h("table", { className: "w-full min-w-[760px] text-left text-sm" }, [
        h(
          "thead",
          { className: "bg-violet-50/80 text-xs uppercase text-violet-800 dark:bg-violet-950/40 dark:text-violet-200" },
          h("tr", null, [
            h("th", { className: "px-4 py-3" }, "ID"),
            h("th", { className: "px-4 py-3" }, "Type"),
            h("th", { className: "px-4 py-3" }, "Target"),
            h("th", { className: "px-4 py-3" }, "Photos"),
            h("th", { className: "px-4 py-3" }, "Status"),
            h("th", { className: "px-4 py-3" }, "Submitted"),
            h("th", { className: "px-4 py-3" }, "Details")
          ])
        ),
        h(
          "tbody",
          { className: "divide-y divide-violet-100/80 dark:divide-white/5" },
          rows.length === 0
            ? h(
                "tr",
                { key: "e" },
                h("td", { colSpan: 7, className: "px-4 py-12 text-center text-sm text-slate-500" }, "You have not submitted any reports yet.")
              )
            : rows.map((r) =>
                h(
                  "tr",
                  { key: r.id, className: "align-top hover:bg-violet-50/40 dark:hover:bg-white/[0.03]" },
                  [
                    h("td", { className: "px-4 py-3 font-mono text-xs" }, shortId(r.id)),
                    h("td", { className: "px-4 py-3 text-slate-700 dark:text-slate-200" }, categoryLabel(r.category)),
                    h("td", { className: "px-4 py-3 text-slate-500" }, [
                      h("div", { key: "t", className: "capitalize" }, r.targetType),
                      r.targetId
                        ? h("div", { key: "i", className: "mt-0.5 font-mono text-[10px] text-slate-400" }, String(r.targetId).slice(-12))
                        : null
                    ].filter(Boolean)),
                    h("td", { className: "px-4 py-3" }, [
                      r.evidenceUrls && r.evidenceUrls.length
                        ? h("div", { key: "ev", className: "flex gap-1" }, r.evidenceUrls.slice(0, 3).map((u) =>
                            h("div", { key: u, className: "h-8 w-8 overflow-hidden rounded-md border border-white/20" }, h("img", { src: u, alt: "", className: "h-full w-full object-cover" }))
                          ))
                        : h("span", { className: "text-xs text-slate-400" }, "—")
                    ]),
                    h("td", { className: "px-4 py-3" }, h(Badge, { tone: reportStatusTone(r.status) }, r.status.replace(/_/g, " "))),
                    h("td", { className: "px-4 py-3 text-xs text-slate-500" }, fmtDate(r.createdAt)),
                    h(
                      "td",
                      { className: "max-w-[280px] px-4 py-3 text-xs text-slate-600 dark:text-slate-300" },
                      [
                        h("p", { key: "d", className: "line-clamp-4 whitespace-pre-wrap break-words" }, r.description),
                        r.adminNote
                          ? h("p", { key: "n", className: "mt-2 rounded-lg border border-violet-200/50 bg-violet-50/80 p-2 text-violet-900 dark:border-violet-500/20 dark:bg-violet-950/30 dark:text-violet-100" }, [
                              h("span", { key: "l", className: "font-semibold" }, "Admin: "),
                              r.adminNote
                            ])
                          : null
                      ].filter(Boolean)
                    )
                  ]
                )
              )
        )
      ])
    ),
    h(ReportsPager, { key: "pg", page, total, limit, onPage: setPage })
  ]);
}

